def parse_rows(rows):
    """Parse all rows and return the orders, oldest first.

    Raises ParseError on the first bad row. See ``parse_rows_lenient`` for a
    version that keeps going.
    """
    orders, rejected = parse_rows_lenient(rows)
    if rejected:
        raise rejected[0][1]
    return orders


def parse_rows_lenient(rows):
    """Parse all rows. Returns (orders oldest first, [(raw_row, ParseError)])."""
    orders, rejected = [], []
    for row in rows:
        try:
            orders.append(parse_row(row))
        except ParseError as exc:
            rejected.append((row, exc))
    orders.sort(key=lambda order: (order.placed_at, order.order_id))
    return orders, rejected

